 static int octal_digit(char c)
 {
     return (c >= '0' && c <= '7');
 }

 static int hex_digit(char c)
 {
     return ((c >= '0' && c <= '9') ||
             (c >= 'A' && c <= 'F') ||
             (c >= 'a' && c <= 'f'));
 }

 static int u8_wc_toutf8(char *dest, uint32_t ch)
 {
     if (ch < 0x80) {
         dest[0] = (char)ch;
         return 1;
     }
     if (ch < 0x800) {
         dest[0] = (ch>>6) | 0xC0;
         dest[1] = (ch & 0x3F) | 0x80;
         return 2;
     }
     if (ch < 0x10000) {
         dest[0] = (ch>>12) | 0xE0;
         dest[1] = ((ch>>6) & 0x3F) | 0x80;
         dest[2] = (ch & 0x3F) | 0x80;
         return 3;
     }
     if (ch < 0x110000) {
         dest[0] = (ch>>18) | 0xF0;
         dest[1] = ((ch>>12) & 0x3F) | 0x80;
         dest[2] = ((ch>>6) & 0x3F) | 0x80;
         dest[3] = (ch & 0x3F) | 0x80;
         return 4;
     }
     return 0;
