 static int u8_read_escape_sequence(const char *str, uint32_t *dest)
 {
     uint32_t ch;
     char digs[9]="\0\0\0\0\0\0\0\0";
     int dno=0, i=1;

     ch = (uint32_t)str[0];    /* take literal character */

     if (str[0] == 'n')
         ch = L'\n';
     else if (str[0] == 't')
         ch = L'\t';
     else if (str[0] == 'r')
         ch = L'\r';
     else if (str[0] == 'b')
         ch = L'\b';
     else if (str[0] == 'f')
         ch = L'\f';
     else if (str[0] == 'v')
         ch = L'\v';
     else if (str[0] == 'a')
         ch = L'\a';
     else if (octal_digit(str[0])) {
         i = 0;
         do {
             digs[dno++] = str[i++];
         } while (octal_digit(str[i]) && dno < 3);
         ch = strtol(digs, NULL, 8);
     }
     else if (str[0] == 'x') {
         while (hex_digit(str[i]) && dno < 2) {
             digs[dno++] = str[i++];
         }
         if (dno > 0)
             ch = strtol(digs, NULL, 16);
     }
     else if (str[0] == 'u') {
         while (hex_digit(str[i]) && dno < 4) {
             digs[dno++] = str[i++];
         }
         if (dno > 0)
             ch = strtol(digs, NULL, 16);
     }
     else if (str[0] == 'U') {
         while (hex_digit(str[i]) && dno < 8) {
             digs[dno++] = str[i++];
         }
         if (dno > 0)
             ch = strtol(digs, NULL, 16);
     }
     *dest = ch;

     return i;
 }

